import type { BankQuestion } from "@/lib/bank";

/** Pedagogy of Maths, EVS and Languages (Child Development & Pedagogy): 100 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cdp-pedagogy-subjects-1", "question": "In the Van Hiele model of geometric thinking, the basic level at which a child recognises shapes by their overall appearance (\"it looks like a door, so it is a rectangle\") is called:", "options": ["Visualisation", "Informal deduction", "Analysis", "Rigour"], "answer": 0, "explanation": "Level 0 (visualisation, or recognition) is based on the look of the whole shape. Analysis (Level 1) is the next level, where children describe a shape by its properties.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-2", "question": "According to the NCF 2005 position on mathematics, the main goal of school mathematics is to develop the child's:", "options": ["speed in mechanical calculation", "memory for formulae", "ability to score well in board examinations", "ability to think mathematically (mathematisation of thought)"], "answer": 3, "explanation": "NCF 2005 names the 'mathematisation' of the child's thinking as the main goal, ahead of narrow goals such as computation speed or rote formulae.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-3", "question": "As recommended by NCF 2005, Environmental Studies (EVS) for Classes III to V is an integrated subject that draws on:", "options": ["language and art education", "history and civics only", "science and mathematics only", "science, social science and environmental education"], "answer": 3, "explanation": "Primary EVS weaves together concerns of science, social science and environmental education instead of teaching them as separate disciplines.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-4", "question": "The four basic language skills, in the order in which a child naturally acquires them, are:", "options": ["Listening, Speaking, Reading, Writing", "Reading, Writing, Listening, Speaking", "Listening, Reading, Speaking, Writing", "Speaking, Listening, Reading, Writing"], "answer": 0, "explanation": "Children listen before they speak, and learn to read before they write: the LSRW sequence. Receptive skills come before productive ones in each pair.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-5", "question": "A Class II child writes 25 + 17 = 312. The error most likely shows that the child:", "options": ["does not know the number names up to 50", "cannot add single-digit numbers", "adds each column separately and writes the whole sum, without regrouping (carrying)", "has a reading disability"], "answer": 2, "explanation": "5 + 7 = 12 is written in full and 2 + 1 = 3 is written beside it, giving 312. The child adds digits correctly but has not grasped place value and carrying.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-6", "question": "Which is the most appropriate way to introduce fractions to Class III children?", "options": ["Writing fractions such as 1/2 and 1/4 on the board", "Giving worksheets on adding unlike fractions", "Defining the numerator and the denominator", "Sharing real objects such as a roti or a sheet of paper equally among children"], "answer": 3, "explanation": "Fractions grow out of the everyday experience of equal sharing. Concrete sharing should come before symbols and definitions.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-7", "question": "The NCERT EVS textbooks for Classes III to V, prepared after NCF 2005, are organised around themes such as:", "options": ["Family and Friends, Food, Shelter, Water, Travel, and Things We Make and Do", "Grammar, Composition and Literature", "Physics, Chemistry and Biology", "Ancient, Medieval and Modern History"], "answer": 0, "explanation": "The primary EVS syllabus uses six child-centred themes: Family and Friends (relationships, work and play, animals, plants), Food, Shelter, Water, Travel, and Things We Make and Do. It avoids subject divisions.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-8", "question": "A teacher asks children to run their eyes quickly over a passage only to find the year in which a dam was built. The reading strategy being practised is:", "options": ["scanning", "intensive reading", "extensive reading", "skimming"], "answer": 0, "explanation": "Scanning means searching a text quickly for one specific piece of information, such as a date or name. Skimming means reading quickly to get the general idea.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-9", "question": "Which classroom practice best reflects the multilingual approach recommended by NCF 2005?", "options": ["Teaching only in English from Class I so that children pick it up faster", "Translating every sentence of the textbook word for word", "Letting children use their home language to express ideas while they learn the school language", "Fining children who speak their mother tongue in school"], "answer": 2, "explanation": "NCF 2005 treats multilingualism as a resource. The child's home language is a bridge to the school language, not something to suppress.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-10", "question": "Using mathematical puzzles and games in a primary class mainly helps to:", "options": ["develop logical reasoning and reduce children's fear of mathematics", "replace the textbook entirely", "test how well children have memorised tables", "keep children busy when the teacher is absent"], "answer": 0, "explanation": "Puzzles and games make children reason, try strategies and enjoy mathematics, which counters maths anxiety. They add to the textbook; they do not replace it.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-11", "question": "Which approach to teaching reading begins with whole, meaningful texts such as stories and rhymes and treats reading as making meaning, not decoding isolated letters?", "options": ["Phonics approach", "Alphabetic method", "Whole language approach", "Grammar-translation method"], "answer": 2, "explanation": "The whole language approach starts from meaningful text and the child's experience. Phonics and the alphabetic method build up from sounds or letters.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-12", "question": "A Class IV teacher takes children to a nearby pond as part of an EVS lesson. The main value of this field visit is that it:", "options": ["gives children a break from studies", "replaces the need for any assessment", "helps the teacher finish the syllabus faster", "lets children observe and explore first-hand and connect learning with their surroundings"], "answer": 3, "explanation": "EVS aims to link classroom knowledge with the child's environment. First-hand observation and exploration on a field visit serve exactly that.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-13", "question": "According to the Van Hiele model, a child who explains that 'a square is also a rectangle, because it has four right angles and its opposite sides are equal' is at the level of:", "options": ["Visualisation", "Formal deduction", "Informal deduction", "Analysis"], "answer": 2, "explanation": "Seeing class inclusion (every square is a rectangle) by relating properties is Level 2, informal deduction (also called abstraction or ordering). At the analysis level, children list properties but treat squares and rectangles as separate.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-14", "question": "Many Class V children say that 0.25 is greater than 0.5 'because 25 is more than 5'. The most effective teaching response is to:", "options": ["ask them to memorise the rule 'compare digit by digit'", "use place-value charts or 10 × 10 grids to show tenths and hundredths visually", "give them more practice on the same kind of sums", "tell them they are being careless"], "answer": 1, "explanation": "The error comes from treating decimals as whole numbers, which is a misconception, not carelessness. Visual models of tenths and hundredths rebuild the concept. Drill or rules alone leave the misconception in place.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-15", "question": "According to NCF 2005, the concerns of EVS in Classes I and II should be:", "options": ["taught as formal science only", "woven into language and mathematics, without a separate EVS textbook", "left out of the curriculum entirely", "taught as a separate subject with its own textbook"], "answer": 1, "explanation": "NCF 2005 says that in Classes I and II the EVS themes should be integrated with language and mathematics. EVS becomes a separate subject from Class III.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-16", "question": "A Class III child insists that 'the sun moves around the earth, because I can see it moving across the sky'. In a constructivist EVS classroom, the teacher should treat this as:", "options": ["evidence of a learning disability", "a sign of low intelligence", "a wrong answer to be crossed out and corrected at once", "an alternative conception based on everyday experience, to be used as a starting point for exploration"], "answer": 3, "explanation": "Children build ideas from experience. Constructivist teaching draws out such alternative conceptions and uses activities and discussion to rebuild them, instead of dismissing them.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-17", "question": "Stephen Krashen's input hypothesis states that a second language is acquired when the learner:", "options": ["receives comprehensible input a little beyond the current level (i + 1)", "is corrected on every error at once", "is taught explicit grammar rules first", "repeats drills until they become habits"], "answer": 0, "explanation": "Krashen argued that acquisition happens through understanding messages slightly beyond one's level (i + 1). Drills and constant correction belong to behaviourist methods.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-18", "question": "A four-year-old says, 'I goed to the market and buyed two mangoes.' From the viewpoint of language development, this shows that the child:", "options": ["has a speech disorder that needs therapy", "should be corrected sharply so the error does not become fixed", "is overgeneralising a grammar rule (adding -ed), a normal sign of active language learning", "is copying incorrect adult speech"], "answer": 2, "explanation": "Overgeneralisation shows the child has worked out the past-tense rule and is applying it to irregular verbs too. Children never hear adults say 'goed', so it is not imitation. It is a normal stage.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-19", "question": "Which assessment task is most suitable for assessing the speaking skill of Class IV children?", "options": ["An oral narration or role-play assessed with a simple rubric", "A multiple-choice test on grammar", "A dictation exercise", "A fill-in-the-blanks worksheet"], "answer": 0, "explanation": "Speaking is a productive oral skill, so it is assessed through actual speaking tasks. The other options assess grammar knowledge, listening-and-writing or reading-and-writing.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-20", "question": "George Pólya's four steps of problem solving, in order, are:", "options": ["Devise a plan, understand the problem, look back, carry out the plan", "Guess, check, revise, conclude", "Understand the problem, devise a plan, carry out the plan, look back", "Read, memorise, calculate, check"], "answer": 2, "explanation": "Pólya's How to Solve It gives understand, plan, carry out and look back (review). The 'look back' step is often skipped in classrooms.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-21", "question": "To teach place value, a teacher first lets children bundle sticks into tens, then shows pictures of the bundles, and finally writes numerals such as 34. This sequence follows:", "options": ["the Van Hiele levels of geometric thought", "Piaget's idea of conservation", "Bruner's enactive, iconic and symbolic modes of representation", "Kohlberg's stages of moral reasoning"], "answer": 2, "explanation": "Handling sticks is enactive, pictures are iconic and numerals are symbolic. This concrete–pictorial–abstract progression comes from Jerome Bruner.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-22", "question": "The idea of 'language across the curriculum' means that:", "options": ["every subject class is also a language class, where children learn the vocabulary and ways of expression of that subject", "children should study as many languages as possible", "English should be the medium for all subjects", "language should be taught only in the language period"], "answer": 0, "explanation": "Language and learning are inseparable. In a science or mathematics lesson, children also learn to describe, explain and argue in the language of that subject.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-23", "question": "In mathematics pedagogy, 'mathematical communication' refers to children's ability to:", "options": ["talk freely during the mathematics period", "recite multiplication tables aloud", "write answers neatly in the notebook", "express, explain and justify mathematical ideas using precise language and symbols"], "answer": 3, "explanation": "Mathematical communication means explaining one's reasoning, using correct terms and symbols, and justifying solutions to others. It is not just talking or neat writing.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-24", "question": "NEP 2020 recommends that, wherever possible, the medium of instruction until at least Grade 5, and preferably till Grade 8 and beyond, should be:", "options": ["Hindi", "Sanskrit", "the home language, mother tongue, local language or regional language", "English"], "answer": 2, "explanation": "NEP 2020 (para 4.11) recommends the home language, mother tongue or local/regional language as the medium of instruction at least till Grade 5, preferably till Grade 8 and beyond.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-25", "question": "How many of the following match the NCF 2005 position on school mathematics? I. The focus should shift from procedures to problem solving and mathematisation. II. Children should see mathematics as something to talk about, communicate and discuss. III. Mathematics should be taught only to children who show an aptitude for it. IV. Algorithms should be taught before children understand the concepts behind them.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II reflect NCF 2005, which wants children to enjoy, discuss and reason about mathematics. III goes against its 'mathematics for all' view, and IV goes against its focus on understanding. So only two match.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-26", "question": "How many of the following statements about the National Curriculum Framework for School Education (NCF-SE) 2023 are correct? I. The Foundational Stage covers ages 3 to 8 (three years of pre-school plus Grades 1 and 2). II. Board examinations are to be offered at least twice a year. III. In Grades 9 and 10 students study three languages, at least two of which are native to India. IV. In Grades 11 and 12 students must study three languages.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: in Grades 11 and 12, NCF-SE 2023 requires two languages, at least one of them native to India. So only three are correct.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-27", "question": "Match the teaching aid with its main use in mathematics: 1. Napier's bones 2. Geoboard 3. Dienes (base-ten) blocks 4. Tangram; a. Place value b. Multiplication c. Making figures from seven geometric pieces d. Area and perimeter using pegs and rubber bands", "options": ["1-a, 2-d, 3-b, 4-c", "1-d, 2-b, 3-c, 4-a", "1-b, 2-c, 3-a, 4-d", "1-b, 2-d, 3-a, 4-c"], "answer": 3, "explanation": "Napier's bones are rods for multiplication. A geoboard uses pegs and rubber bands to explore area and perimeter. Dienes blocks (units, longs, flats) model place value. A tangram has seven pieces for composing figures.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-28", "question": "Assertion (A): Teachers should encourage children to estimate an answer before working it out. Reason (R): Estimation helps children judge whether an answer is reasonable and builds number sense.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A: estimating first gives a benchmark for spotting unreasonable answers and strengthens number sense, which is why it is encouraged.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-29", "question": "Assertion (A): Correcting every error a child makes while speaking a new language is the best way to ensure accuracy. Reason (R): Errors are a natural part of language learning and reveal the child's developing ideas about how the language works.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is true: errors are windows into the learner's developing grammar. A is false, because constant correction discourages children from speaking and harms fluency. Errors call for selective, sensitive feedback.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-30", "question": "How many of the following statements about EVS at the primary level, as envisaged in NCF 2005, are correct? I. EVS is taught as a separate subject with its own textbook from Class I onwards. II. It aims to connect children's learning in school with their life outside school. III. It is to be assessed mainly through written tests of definitions. IV. Its themes are presented from the child's point of view rather than through subject divisions.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II and IV are correct. I is wrong, because EVS is a separate subject only from Class III (it is integrated with language and maths in Classes I–II). III is wrong, because NCF 2005 wants continuous assessment through observation, activities and projects, not tests of definitions. So only two.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-31", "question": "Which of the following is NOT a feature of the communicative approach to language teaching?", "options": ["A focus on meaning and fluency", "Insisting on grammatical accuracy through mechanical drills before any real use of the language", "Using real-life tasks such as asking for directions", "Plenty of pair and group work"], "answer": 1, "explanation": "The communicative approach puts meaningful use first, through real tasks, interaction and fluency. Mechanical drilling for accuracy before use belongs to the structural or audio-lingual methods.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-32", "question": "While counting six marbles, a child says 'one, two, three, four, five, six, seven' in the correct order but touches one marble twice. Which counting principle has the child not yet mastered?", "options": ["One-to-one correspondence", "Cardinality", "Stable order", "Order irrelevance"], "answer": 0, "explanation": "Each object must get exactly one number word (one-to-one correspondence), and touching a marble twice breaks this. The number words came in the right order, so the stable-order principle is intact.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-33", "question": "After correctly counting seven pencils, a child is asked 'So how many pencils are there?' and starts counting all over again instead of answering 'seven'. The child has not yet grasped the principle of:", "options": ["cardinality", "abstraction", "one-to-one correspondence", "stable order"], "answer": 0, "explanation": "Cardinality means the last number word said gives the size of the whole set. A child who recounts has not linked 'seven' to the total, even though the counting itself was correct.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-34", "question": "Phonemic awareness is best shown when a child can:", "options": ["copy words neatly from the board", "say that 'cat' without its first sound /k/ becomes 'at'", "name the letter C when it is shown", "read a sentence aloud fluently"], "answer": 1, "explanation": "Phonemic awareness is the ability to hear and handle individual sounds in spoken words, e.g. taking away the first sound. Naming letters is letter knowledge, and fluent reading is a later skill.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-35", "question": "Which question best assesses a Class V child's conceptual understanding of fractions rather than procedural skill?", "options": ["Without calculating, explain why 3/4 is greater than 3/5", "Convert 3/4 into a decimal", "Add 3/4 and 3/5", "Find the LCM of 4 and 5"], "answer": 0, "explanation": "Explaining that the same number of larger parts (quarters are bigger than fifths) makes a larger fraction needs understanding. The other tasks can be done by following a learned procedure.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-36", "question": "An EVS chapter for Class IV asks children: 'Who cooks food in your family? Who fetches water? Why?' The main purpose of such questions is to:", "options": ["test children's memory of family members' names", "teach children recipes", "help children reflect on gender roles and the division of work in their own families", "collect household data for the school records"], "answer": 2, "explanation": "Primary EVS uses open questions from the child's own life to raise social issues such as gender, work and equity, so children think critically about everyday roles.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-37", "question": "How many of the following statements about NEP 2020 are correct? I. It gives the highest priority to achieving universal foundational literacy and numeracy in primary school by 2025. II. The NIPUN Bharat mission was launched to work towards foundational literacy and numeracy goals. III. It keeps the three-language formula but adds flexibility, saying no language will be imposed on any state. IV. It makes English the compulsory medium of instruction from Grade 1.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (NIPUN Bharat was launched in 2021 to pursue FLN). IV is wrong, because NEP 2020 prefers the mother tongue or regional language as the medium of instruction in the early grades. So only three.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-38", "question": "How many of the following statements about teaching reading and writing in the primary grades are correct? I. The aim of reading instruction is reading with comprehension, not just decoding. II. Using children's literature in class supports language development. III. A print-rich classroom environment supports emergent literacy. IV. A child's home language is a resource for learning the school language.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four reflect current language pedagogy (NCF 2005, NCF-FS 2022 and NEP 2020). Reading is meaning-making, children's literature and print-rich classrooms support literacy, and the home language is a bridge, not a barrier.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-39", "question": "Which sequence is most appropriate for teaching the measurement of length in the primary classes?", "options": ["The need for a standard unit, then using a ruler, then direct comparison, then non-standard units", "Non-standard units, then using a ruler, then direct comparison, then the need for a standard unit", "Direct comparison of objects, then non-standard units (hand span, pencil), then the need for a standard unit, then using a ruler", "Using a ruler, then non-standard units, then direct comparison, then the need for a standard unit"], "answer": 2, "explanation": "Children first compare lengths directly (longer or shorter), then measure with body or object units. They see that different hand spans give different answers, which creates the need for a standard unit, and only then use the ruler.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-40", "question": "Which of the following is NOT one of the five guiding principles of NCF 2005?", "options": ["Making board examinations compulsory at the end of Class VIII", "Making examinations more flexible and integrated with classroom life", "Moving learning away from rote methods", "Connecting knowledge to life outside the school"], "answer": 0, "explanation": "The five guiding principles are: connecting knowledge to life outside school, moving away from rote learning, enriching the curriculum beyond textbooks, making examinations flexible and integrated with classroom life, and nurturing an overriding identity informed by caring concerns within the democratic polity. A Class VIII board exam is not one of them.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-41", "question": "The NCERT textbooks for Environmental Studies (Classes III to V) are titled:", "options": ["Looking Around", "Rimjhim", "Math-Magic", "Marigold"], "answer": 0, "explanation": "“Looking Around” is the NCERT EVS series. Rimjhim is the Hindi reader, Math-Magic the mathematics series and Marigold the English reader for the primary classes.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-42", "question": "A specific learning disability that mainly affects understanding numbers and doing calculations is called:", "options": ["Dyslexia", "Dysgraphia", "Dyscalculia", "Dyspraxia"], "answer": 2, "explanation": "Dyscalculia affects number sense and calculation. Dyslexia affects reading, dysgraphia writing, and dyspraxia motor coordination.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-43", "question": "Which is the most suitable way to begin addition with Class I children?", "options": ["Memorising addition tables", "Writing long columns of sums on the board", "Practising abstract symbols only", "Combining and counting real objects such as pebbles and seeds"], "answer": 3, "explanation": "Young children are at a concrete stage; joining real collections and counting gives meaning to “adding” before symbols are introduced.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-44", "question": "A Class III child writes 52 − 27 = 35. What is the most likely reason for this error?", "options": ["Carelessness in copying the numbers", "In each column the child subtracts the smaller digit from the larger, ignoring regrouping", "The child does not know subtraction facts up to 10", "The child has added instead of subtracted"], "answer": 1, "explanation": "In the ones place the child did 7 − 2 = 5 instead of regrouping, then 5 − 2 = 3. This systematic “smaller-from-larger” error shows a gap in understanding place value and borrowing.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-45", "question": "A teacher shows children many triangles, has them measure the angles, and helps them conclude that the angles of a triangle add up to 180°. This is the:", "options": ["Deductive method", "Lecture method", "Inductive method", "Analytic method"], "answer": 2, "explanation": "The inductive method moves from specific examples to a general rule, which suits young learners. The deductive method starts with the rule and then applies it.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-46", "question": "Which of these is NOT one of the six themes around which the NCERT EVS books for Classes III–V are organised?", "options": ["Water", "Travel", "Things We Make and Do", "Our Solar System"], "answer": 3, "explanation": "The six themes are Family and Friends, Food, Shelter, Water, Travel, and Things We Make and Do. The books deliberately avoid organising content by disciplines such as astronomy.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-47", "question": "In the 5E model of inquiry-based teaching used in science and EVS, the phases occur in which order?", "options": ["Engage, Explore, Explain, Elaborate, Evaluate", "Explain, Engage, Explore, Evaluate, Elaborate", "Explore, Engage, Explain, Evaluate, Elaborate", "Engage, Explain, Explore, Elaborate, Evaluate"], "answer": 0, "explanation": "Children are first engaged by a question, then explore, then explain what they found, elaborate by applying it, and finally evaluate their understanding.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-48", "question": "The project method of teaching, built on Dewey's ideas of learning by doing, was developed by:", "options": ["Maria Montessori", "W. H. Kilpatrick", "H. E. Armstrong", "Friedrich Froebel"], "answer": 1, "explanation": "William Heard Kilpatrick proposed the project method (1918). Armstrong is linked with the heuristic method and Froebel with the kindergarten.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-49", "question": "Richard Skemp distinguished “relational understanding” from “instrumental understanding”. Relational understanding means:", "options": ["Knowing a rule and how to apply it quickly", "Knowing both what to do and why it works", "Memorising formulae through repeated practice", "Relating mathematics only to daily life examples"], "answer": 1, "explanation": "Instrumental understanding is “rules without reasons”; relational understanding connects procedures to the underlying concepts, so it transfers better to new problems.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-50", "question": "To study the theme “Water” in Class IV, which activity best fits the approach of NCF 2005?", "options": ["Copying the definition of the water cycle five times", "Reading the chapter aloud and answering textbook questions", "Surveying water sources in the neighbourhood and discussing who fetches water and how far", "Memorising the names of major rivers of the world"], "answer": 2, "explanation": "A local survey links the theme to children's own lives, involves observation and recording, and raises issues of access and equity, as NCF 2005 recommends.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-51", "question": "Zoltan Dienes's “perceptual variability” (multiple embodiment) principle means that a mathematical concept should be:", "options": ["Taught through only one well-chosen model", "Presented through several different concrete materials and situations", "Introduced first as a formal definition", "Practised until answers become automatic"], "answer": 1, "explanation": "Meeting the same idea, such as place value, in sticks, beads and blocks helps children abstract what is common and not tie the concept to one material.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-52", "question": "Many children think that multiplying always gives a bigger number, so they are puzzled that 1/2 × 1/4 = 1/8. The best teaching response is to:", "options": ["Tell them the rule and ask them to memorise it", "Use area models to show that taking a part of a part gives a smaller part", "Avoid fraction multiplication until Class VIII", "Give a large number of similar sums for drill"], "answer": 1, "explanation": "The belief comes from experience with whole numbers. An area or paper-folding model shows that “half of a quarter” is smaller than both, correcting the misconception through meaning.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-53", "question": "A child correctly lists the properties of a square (four equal sides, four right angles) but insists that a square is not a rectangle. According to Van Hiele, the child is at the level of:", "options": ["Visualisation", "Analysis", "Informal deduction", "Rigour"], "answer": 1, "explanation": "At the analysis level children describe shapes by their properties but do not yet see relationships between classes of shapes, which comes at informal deduction.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-54", "question": "The heuristic method, in which the learner is put in the position of a discoverer, was advocated by:", "options": ["H. E. Armstrong", "W. H. Kilpatrick", "J. S. Bruner", "B. F. Skinner"], "answer": 0, "explanation": "Henry Edward Armstrong promoted the heuristic method in science teaching. Bruner is linked with discovery learning more generally and Skinner with programmed instruction.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-55", "question": "Concept maps, used in EVS and science to show how ideas are linked, were developed by:", "options": ["Jean Piaget", "Joseph Novak", "Howard Gardner", "Benjamin Bloom"], "answer": 1, "explanation": "Joseph Novak developed concept mapping in the 1970s, building on Ausubel's idea that meaningful learning links new ideas to existing knowledge.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-56", "question": "Which of these is an open-ended task in mathematics?", "options": ["What is 12 + 8?", "Find as many pairs of numbers as you can whose sum is 20.", "Write the multiplication table of 4.", "Copy the numbers from 1 to 50."], "answer": 1, "explanation": "An open-ended task has many correct answers and lets children use different strategies and reasoning. The other tasks have a single fixed answer.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-57", "question": "NCERT's indicators for assessing learning in EVS include all of the following EXCEPT:", "options": ["Observation and recording", "Classification", "Concern for justice and equality", "Reproducing textbook definitions word for word"], "answer": 3, "explanation": "The EVS indicators include observation and recording, discussion, expression, explanation, classification, questioning, analysis, experimentation, concern for justice and equality, and cooperation. Rote reproduction is not an indicator.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-58", "question": "In a geometry proof, working backwards from what is to be proved towards what is already known is called the:", "options": ["Synthetic method", "Inductive method", "Analytic method", "Laboratory method"], "answer": 2, "explanation": "The analytic method goes from the unknown to the known and helps children discover the proof. The synthetic method presents the proof from known facts to the conclusion.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-59", "question": "Which is a major limitation of using the deductive method alone with young children in mathematics?", "options": ["It takes too long to complete the syllabus", "It may lead to memorising formulae without understanding where they come from", "It needs costly laboratory equipment", "It cannot be used for geometry"], "answer": 1, "explanation": "Starting with a ready-made rule is quick, but children may apply it mechanically. Combining it with the inductive method builds understanding first.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-60", "question": "Activities in which children extend number and shape patterns (2, 4, 6, 8, …) mainly help them to develop:", "options": ["Speed in written computation", "Generalisation and early algebraic thinking", "Neat handwriting of numerals", "Memory of multiplication tables"], "answer": 1, "explanation": "Recognising and describing a rule behind a pattern is the root of algebraic thinking; NCF 2005 gives patterns a place from the early grades.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-61", "question": "Assertion (A): EVS in the primary classes should begin from the child's immediate surroundings. Reason (R): Children construct new knowledge by linking new experiences to what they already know.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Starting from home, family and neighbourhood gives children a base of experience to build on, in line with constructivism.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-62", "question": "Consider the following statements about the NCERT EVS books for Classes III–V: 1. They follow a thematic organisation rather than separate science and social science chapters. 2. Their exercises are designed mainly for rote recall of definitions. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. The exercises ask children to observe, discuss, find out from elders and express their views, not to reproduce definitions.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-63", "question": "Arrange these Van Hiele levels in the order in which they develop: 1. Deduction 2. Analysis 3. Rigour 4. Informal deduction", "options": ["2, 4, 1, 3", "2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "After visualisation come analysis, informal deduction (abstraction), formal deduction and finally rigour.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-64", "question": "How many of these statements about the NIPUN Bharat Mission are correct? I. It was launched in 2021. II. It aims for every child to achieve foundational literacy and numeracy by the end of Grade 3. III. Its target year is 2026–27. IV. It covers children in the age group of 3 to 9 years.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. NIPUN Bharat implements the NEP 2020 priority on foundational literacy and numeracy.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-65", "question": "Consider the following statements: 1. Vidya Pravesh is a three-month, play-based school preparation module for children entering Grade 1. 2. It was launched as part of implementing NEP 2020. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Vidya Pravesh eases the move to school through play, stories and activities before formal instruction.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-66", "question": "Assertion (A): Children should be allowed to use their own informal strategies for addition before the standard algorithm is taught. Reason (R): Standard algorithms are always inefficient and should be avoided.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: invented strategies build number sense and make the algorithm meaningful later. R is false: standard algorithms are efficient tools once understood.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-67", "question": "A Class V child writes 1/2 + 1/3 = 2/5. Which response best addresses the misconception?", "options": ["Make the child repeat the rule for finding the LCM", "Use fraction strips or area models to show that halves and thirds must be changed to equal-sized parts before adding", "Mark the answer wrong and move on", "Give twenty similar sums for homework"], "answer": 1, "explanation": "The child is treating numerators and denominators as separate whole numbers. Models show why common-sized parts (sixths) are needed, giving meaning to the procedure.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-68", "question": "Which question in an EVS lesson on houses most encourages higher-order thinking?", "options": ["Name two types of houses.", "What is a house made of mud called?", "Why do you think many houses in Rajasthan have thick walls and small windows?", "Which material is used for roofs in your textbook picture?"], "answer": 2, "explanation": "Asking “why” makes children link climate and building design, which calls for reasoning and inference rather than recall.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-69", "question": "Consider the following statements: 1. Formative assessment in mathematics can include observing the strategies children use during group work. 2. Summative assessment results should be used to label children as slow learners. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. Assessment is meant to improve teaching and learning; labelling children harms their confidence and is discouraged by NCF 2005.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-70", "question": "In the grammar-translation method of teaching a language:", "options": ["Only the target language is used in class", "Learning happens through drills and habit formation", "Children learn through real-life communicative tasks", "Grammar rules are taught explicitly and texts are translated using the mother tongue"], "answer": 3, "explanation": "Grammar-translation relies on rules, vocabulary lists and translation, with little speaking practice. The direct method bans translation; audio-lingual uses drills.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-71", "question": "A child who has persistent difficulty in forming letters, spacing words and writing legibly may have:", "options": ["Dysgraphia", "Dyscalculia", "Aphasia", "Dyslexia"], "answer": 0, "explanation": "Dysgraphia is a learning disability affecting handwriting and written expression. Dyslexia affects reading; aphasia is loss of language ability, usually after brain injury.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-72", "question": "A teacher asks children to read a passage quickly to get its general idea before reading it closely. This reading strategy is called:", "options": ["Scanning", "Intensive reading", "Loud reading", "Skimming"], "answer": 3, "explanation": "Skimming is quick reading for the gist; scanning is searching for a specific detail such as a name or date.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-73", "question": "Noam Chomsky held that children learn language easily because they are born with:", "options": ["A blank slate shaped wholly by reinforcement", "A Language Acquisition Device", "A fixed vocabulary of a few hundred words", "An ability that appears only after schooling"], "answer": 1, "explanation": "Chomsky argued for an innate Language Acquisition Device and a universal grammar, against Skinner's view that language is learnt only through imitation and reinforcement.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-74", "question": "According to B. F. Skinner, children acquire language mainly through:", "options": ["An innate universal grammar", "Social interaction within the zone of proximal development", "Imitation and reinforcement", "Biological maturation alone"], "answer": 2, "explanation": "Skinner's behaviourist view (Verbal Behavior, 1957) explains language as habits shaped by reinforcement. Chomsky criticised it for not explaining children's novel sentences.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-75", "question": "A test in which children fill in words deleted at regular intervals from a passage is called a:", "options": ["Dictation test", "Cloze test", "True–false test", "Matching test"], "answer": 1, "explanation": "A cloze test checks comprehension and language knowledge, since filling the gaps needs understanding of the context and grammar.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-76", "question": "In the process approach to writing, which sequence is correct?", "options": ["Editing, drafting, brainstorming, revising", "Drafting, brainstorming, editing, revising", "Brainstorming, editing, drafting, revising", "Brainstorming, drafting, revising, editing"], "answer": 3, "explanation": "Writers first generate ideas, then write a draft, revise its content and organisation, and finally edit for language and mechanics before publishing.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-77", "question": "The phonics approach to teaching reading focuses on:", "options": ["Guessing words from pictures only", "Memorising whole texts", "Teaching the relationship between letters and the sounds they stand for", "Reading silently from the start"], "answer": 2, "explanation": "Phonics teaches sound–symbol correspondence so that children can decode new words. It works best alongside meaningful reading, not in isolation.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-78", "question": "Which is the most effective way to build the vocabulary of young learners?", "options": ["Making them meet new words repeatedly in stories, songs and conversation", "Giving lists of words with meanings to memorise", "Testing spellings every day", "Asking them to copy dictionary entries"], "answer": 0, "explanation": "Words are learnt best in meaningful context with repeated exposure; isolated lists are quickly forgotten.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-79", "question": "Who held that thought and language develop from separate roots and come together at about the age of two, when thought becomes verbal and speech becomes rational?", "options": ["Jean Piaget", "Noam Chomsky", "B. F. Skinner", "Lev Vygotsky"], "answer": 3, "explanation": "Vygotsky (Thought and Language) described this meeting of thought and speech. Piaget saw language as reflecting thought, and Chomsky stressed innate grammar.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-80", "question": "According to Krashen's affective filter hypothesis, a learner's acquisition of a second language is blocked mainly by:", "options": ["Too much comprehensible input", "Anxiety, low motivation and low self-confidence", "Learning grammar after vocabulary", "Using the mother tongue at home"], "answer": 1, "explanation": "A high affective filter keeps input from being acquired. A relaxed classroom where mistakes are accepted lowers the filter.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-81", "question": "Consider the following statements based on Krashen's theory: 1. Acquisition is a subconscious process similar to how children pick up their first language. 2. Learning refers to conscious knowledge of the rules of a language. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Krashen argued that fluency comes mainly from acquisition, while consciously learnt rules mostly serve as a monitor.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-82", "question": "After a story, which question checks inferential comprehension?", "options": ["What was the name of the old man?", "Where did the old man live?", "How many goats did the old man have?", "Why do you think the old man smiled at the end?"], "answer": 3, "explanation": "Inferential questions need children to read between the lines. The others are literal questions whose answers are stated in the text.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-83", "question": "The three-language formula was recommended by the Kothari Commission and adopted in the:", "options": ["National Policy on Education, 1968", "National Policy on Education, 1986", "Right to Education Act, 2009", "National Curriculum Framework, 2005"], "answer": 0, "explanation": "The Education Commission (1964–66) recommended it and the 1968 policy adopted it. NCF 2005 and NEP 2020 reaffirmed it with flexibility.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-84", "question": "Which Article of the Constitution asks every State to provide facilities for instruction in the mother tongue at the primary stage to children of linguistic minority groups?", "options": ["Article 45", "Article 29", "Article 21A", "Article 350A"], "answer": 3, "explanation": "Article 350A, added in 1956, deals with mother-tongue instruction. Article 29 protects culture and language, and Article 21A is the right to education.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-85", "question": "A Class I teacher labels objects in the room, displays children's names, charts and posters at their eye level. The main purpose is to:", "options": ["Decorate the classroom for inspections", "Create a print-rich environment that supports emergent literacy", "Make children copy the labels as handwriting practice", "Test children's spelling"], "answer": 1, "explanation": "Seeing meaningful print around them helps children notice that print carries meaning and supports early reading and writing.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-86", "question": "“Big Books” in early-grade classrooms are mainly used for:", "options": ["Silent individual reading", "Shared reading, in which the whole class can see the text and pictures while the teacher reads", "Testing spellings", "Copying text into notebooks"], "answer": 1, "explanation": "Big Books let the teacher model reading, point to words and invite predictions, so children join in reading together.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-87", "question": "A child often reverses letters such as b and d. Which remedial approach is most suitable?", "options": ["Making the child write each letter a hundred times", "Scolding the child for carelessness", "A multisensory approach, such as tracing letters in sand while saying their sounds", "Moving the child to a lower class"], "answer": 2, "explanation": "Multisensory methods link sight, sound, movement and touch, which helps children with reversal difficulties; punishment and drills do not.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-88", "question": "Which task is most suitable for assessing the listening skill of Class III children?", "options": ["Copying a paragraph from the board", "Writing an essay on “My School”", "Reading a passage aloud", "Listening to a short announcement and answering questions about it"], "answer": 3, "explanation": "A listening task needs a spoken input and a response that shows understanding. The other tasks assess writing or reading.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-89", "question": "While reading a story aloud, a teacher stops and asks, “What do you think will happen next?” This mainly develops children's:", "options": ["Handwriting", "Ability to predict and engage actively with the text", "Memory for spelling", "Speed of silent reading"], "answer": 1, "explanation": "Predicting makes children use clues from the text and their own experience, which builds active comprehension.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-90", "question": "Consider the following statements based on Krashen's theory: 1. The monitor hypothesis says consciously learnt rules act as an editor on what the learner produces. 2. The natural order hypothesis says grammatical structures are acquired in a broadly predictable order. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Together with the input, acquisition–learning and affective filter hypotheses, these make up Krashen's five hypotheses.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-91", "question": "Match the language teaching method with its feature: A. Grammar-translation B. Direct method C. Audio-lingual method D. Communicative approach — 1. Drills and habit formation 2. Meaningful interaction through real-life tasks 3. Translation and explicit rules 4. Target language only, no translation", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Grammar-translation uses translation and rules, the direct method avoids the mother tongue, the audio-lingual method uses behaviourist drills, and the communicative approach stresses meaningful use.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-92", "question": "How many of these statements about language policy in education are correct? I. The Kothari Commission recommended the three-language formula. II. Article 350A concerns mother-tongue instruction at the primary stage. III. Article 351 directs the Union to promote the spread of Hindi. IV. NEP 2020 makes it compulsory for every State to teach a particular language.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. NEP 2020 states that no language will be imposed on any State; the choice of languages rests with States and students.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-93", "question": "Arrange these levels of reading comprehension in increasing order of cognitive demand: 1. Evaluative (critical) 2. Literal 3. Inferential", "options": ["2, 3, 1", "3, 2, 1", "2, 1, 3", "1, 3, 2"], "answer": 0, "explanation": "Literal comprehension recalls what is stated, inferential reads between the lines, and evaluative comprehension judges the text against one's own values and knowledge.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-94", "question": "Consider the following statements: 1. Dictation can assess listening and writing together. 2. A cloze test assesses only spelling. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. A cloze test checks comprehension, vocabulary and grammar, since the missing words must fit the meaning of the passage.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-95", "question": "Assertion (A): Children should learn the whole alphabet in order before they are exposed to any meaningful text. Reason (R): Reading is mainly the decoding of letters and has little to do with meaning.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "Both A and R are false"], "answer": 3, "explanation": "Both are false. Reading is making meaning from text; children benefit from stories and print from the start, with decoding skills taught alongside, not before.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-96", "question": "A Class II child reads a story aloud fluently but cannot answer simple questions about it. What should the teacher focus on?", "options": ["More practice in loud, fast reading", "Comprehension through discussion, questioning and relating the story to the child's experience", "Spelling tests on the story's words", "Copying the story into the notebook"], "answer": 1, "explanation": "The child can decode but is not making meaning. Talking about the story, predicting and connecting it to life build comprehension.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-97", "question": "Which classroom arrangement best supports a child with a hearing impairment in a language class?", "options": ["Seating the child at the back to avoid distraction", "Speaking faster so the lesson is covered", "Turning to the board while speaking", "Seating the child where the teacher's face is clearly visible and using visual aids and gestures"], "answer": 3, "explanation": "Seeing the speaker's face helps lip-reading, and visual support makes content accessible, in line with inclusive education under the RPwD Act, 2016.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-98", "question": "How many of these statements about the process approach to writing are correct? I. It focuses on the stages through which a piece of writing is composed. II. Feedback from peers is valued. III. Only the final product is assessed. IV. Drafts are revised before the final version.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The process approach also values and assesses drafts and revisions, not just the finished product.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-99", "question": "Consider the following statements: 1. Phonemic awareness is an oral skill and can be developed without print, for example through rhymes and sound games. 2. Phonics connects sounds with written letters. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Phonemic awareness (hearing and playing with sounds) usually comes first and supports later phonics instruction.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-100", "question": "A teacher lets children answer in their home language during an English lesson and then helps them express the same idea in English. This practice is best described as:", "options": ["Using the mother tongue as a resource for learning a new language", "Lowering the standard of English teaching", "The grammar-translation method", "Avoiding the target language"], "answer": 0, "explanation": "NCF 2005 treats multilingualism as a resource; building on the home language lets children participate and gradually move to English.", "difficulty": "hard", "source": "CTET · State TETs"},
];

export default questions;
